mapper.update:
update plm_ppap_elem
   set req_cd = #{reqCd}, status = #{status}, file_id = #{fileId,jdbcType=BIGINT}, note = #{note,jdbcType=VARCHAR},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where ppap_id = #{ppapId} and elem_no = #{elemNo}
   and (req_cd <> #{reqCd} or status <> #{status} or file_id is distinct from #{fileId,jdbcType=BIGINT}
        or note is distinct from #{note,jdbcType=VARCHAR})

update plm_ppap_elem
   set apqp_kind = #{kind,jdbcType=VARCHAR}, apqp_rev_id = #{revId,jdbcType=BIGINT}, apqp_label = #{label,jdbcType=VARCHAR},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where ppap_id = #{ppapId} and elem_no = #{elemNo}
   and (apqp_kind is distinct from #{kind,jdbcType=VARCHAR} or apqp_rev_id is distinct from #{revId,jdbcType=BIGINT}
        or apqp_label is distinct from #{label,jdbcType=VARCHAR})

update plm_ppap set status = #{status}, decided_on = #{on}, decision_ref = #{ref,jdbcType=VARCHAR},
       decision_note = #{note,jdbcType=VARCHAR}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where ppap_id = #{ppapId} and row_ver = #{rowVer} and status = 'SUBMITTED'

update plm_ppap set status = 'DRAFT', decided_on = null, decision_ref = null, decision_note = null,
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where ppap_id = #{ppapId} and row_ver = #{rowVer} and status in ('INTERIM', 'REJECTED')

update plm_eco set cust_approval_status = 'APPROVED', cust_approval_ref = #{ref}, cust_approved_on = #{on},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where eco_id = #{ecoId} and cust_approval_req_yn = 'Y' and cust_id = #{custId}
   and status in ('DRAFT', 'PENDING', 'APPROVED')

update plm_pcn set status = #{status}, responded_on = #{on}, response_note = #{note,jdbcType=VARCHAR},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where pcn_id = #{pcnId} and row_ver = #{rowVer} and status = 'SENT'
